import { useState } from 'react';
import { JxCalendar, JxChip } from '@jinx-ui/react';

interface ReportDatePickerProps {
  onChange?: (value: Date | null) => void;
}

function startOfDay(date: Date): Date {
  const result = new Date(date);
  result.setHours(0, 0, 0, 0);
  return result;
}

function addDays(date: Date, days: number): Date {
  const result = new Date(date);
  result.setDate(result.getDate() + days);
  return result;
}

function isSameDay(a: Date | null, b: Date): boolean {
  if (!a) return false;
  return (
    a.getFullYear() === b.getFullYear() &&
    a.getMonth() === b.getMonth() &&
    a.getDate() === b.getDate()
  );
}

export default function ReportDatePicker({ onChange }: ReportDatePickerProps) {
  const [date, setDate] = useState<Date | null>(null);

  const today = startOfDay(new Date());
  const yesterday = startOfDay(addDays(today, -1));
  const weekAgo = startOfDay(addDays(today, -7));

  const presets = [
    { label: 'Сегодня', value: today },
    { label: 'Вчера', value: yesterday },
    { label: 'Неделя назад', value: weekAgo },
  ];

  const handleChange = (value: Date | null) => {
    setDate(value);
    onChange?.(value);
  };

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-r-sm)' }}>
      <div style={{ display: 'flex', gap: 'var(--jx-r-xs)' }}>
        {presets.map((preset) => (
          <JxChip
            key={preset.label}
            active={isSameDay(date, preset.value)}
            onClick={() => handleChange(preset.value)}
          >
            {preset.label}
          </JxChip>
        ))}
      </div>
      <JxCalendar locale="ru-RU" value={date} onValueChange={handleChange} />
    </div>
  );
}

